import{_ as d,o as e,c as o,a5 as c}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Test — Subtask theo vai trò & Trình soạn chia phần (DA-1274)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/subtask-role-workspaces/test.md","filePath":"feature/subtask-role-workspaces/test.md"}'),n={name:"feature/subtask-role-workspaces/test.md"};function h(a,t,i,r,s,g){return e(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="test-—-subtask-theo-vai-tro-trinh-soan-chia-phan-da-1274" tabindex="-1">Test — Subtask theo vai trò &amp; Trình soạn chia phần (DA-1274) <a class="header-anchor" href="#test-—-subtask-theo-vai-tro-trinh-soan-chia-phan-da-1274" aria-label="Permalink to &quot;Test — Subtask theo vai trò &amp; Trình soạn chia phần (DA-1274)&quot;">​</a></h1><p>&gt; Bước ④ theo <code>docs/rule/feature-workflow.md</code>. Dựa trên <code>spec.md</code> (AC1–AC20, §11, §13, §16), <code>plan.md</code>, <code>task.md</code>. &gt; Cột <strong>Map</strong> chỉ AC / mục spec / task tương ứng. Cột <strong>KQ</strong> ghi <code>PASS</code> / <code>FAIL</code> / <code>N/A</code> khi chạy T10.5. &gt; Tầng: <strong>U</strong> = unit, <strong>I</strong> = integration (MockMvc + Mongo/Postgres test), <strong>E</strong> = E2E web (Playwright), <strong>M</strong> = mobile (Jest/RNTL), <strong>T</strong> = thủ công.</p><h2 id="du-lieu-chuan-bi" tabindex="-1">Dữ liệu chuẩn bị <a class="header-anchor" href="#du-lieu-chuan-bi" aria-label="Permalink to &quot;Dữ liệu chuẩn bị&quot;">​</a></h2><ul><li>Workspace W1 thuộc agency A1 (gói BASIC), Client C1 (<code>displayName = &quot;Brand X&quot;</code>, có logo). Workspace W2 cùng agency A1, cùng Client C1.</li><li>Người dùng: <code>mgr</code> (Manager W1), <code>owner</code> (Owner A1), <code>coord</code> (Creator, assignee task cha), <code>res</code>, <code>content</code>, <code>content2</code>, <code>media</code>, <code>edit</code>, <code>pub</code> (Creator, mỗi người 1 subtask vai trò POST tương ứng), <code>free</code> (Creator, subtask tự do), <code>outsider</code> (Creator W1, không tham gia task), <code>sup</code> (supervisor subtask <code>POST_MEDIA</code>), <code>client</code> (tài khoản Client C1).</li><li>Task P1: POST, <code>requiresClientApproval = true</code>, có 5 subtask vai trò + 1 subtask tự do (seed T3.7).</li><li>Task P2: POST cũ, chỉ có subtask <code>subtaskRole = null</code>.</li><li>Task N1: EMAIL_NEWSLETTER, đủ 4 subtask vai trò; nhóm người nhận G1 của C1.</li><li>File CSV mẫu: <code>contacts-10.csv</code> (10 dòng: 7 hợp lệ, 2 <code>consent = no</code>, 1 email nằm trong suppression).</li></ul><hr><h2 id="a-danh-muc-subtask" tabindex="-1">A. Danh mục &amp; subtask <a class="header-anchor" href="#a-danh-muc-subtask" aria-label="Permalink to &quot;A. Danh mục &amp; subtask&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Map</th><th>Tầng</th><th>Bước / Input</th><th>Mong đợi</th><th>KQ</th></tr></thead><tbody><tr><td>A1</td><td>AC1, T1.3, T1.6</td><td>U+I</td><td><code>GET /api/v1/task-catalog/{type}</code> cho 8 loại</td><td>Số vai trò/phần đúng spec §3: POST 5 vai trò/4 phần, SHORT_VIDEO 4/5, SURVEY 3/3, EVENT_PLAN 5/5, PRESS 4/4, KOL 5/5, WORKSHOP 5/5, EMAIL 4/4. Cờ O/I khớp bảng.</td><td>☐</td></tr><tr><td>A2</td><td>AC1, T1.6</td><td>I</td><td><code>GET /task-catalog/ABC</code></td><td><code>VALIDATION_ERROR</code></td><td>☐</td></tr><tr><td>A3</td><td>AC2, T1.7</td><td>I</td><td>Tạo subtask <code>subtaskRole = POST_CONTENT</code> trên P1; tạo subtask không có <code>subtaskRole</code></td><td>Lần 1 lưu <code>POST_CONTENT</code>; lần 2 lưu <code>null</code>. <code>GET</code> subtask trả <code>subtaskRole</code> ở <code>Details</code> và <code>Row</code>.</td><td>☐</td></tr><tr><td>A4</td><td>AC2, T1.5</td><td>I</td><td>Đọc subtask cũ của P2 (document không có field <code>subtaskRole</code>)</td><td>Trả <code>subtaskRole = null</code>, không lỗi deserialize.</td><td>☐</td></tr><tr><td>A5</td><td>AC3, T1.7</td><td>I</td><td>Tạo subtask <code>subtaskRole = KOL_BRIEF</code> trên P1 (POST)</td><td><code>VALIDATION_ERROR</code> (<code>tasks.subtask.invalidRole</code>).</td><td>☐</td></tr><tr><td>A6</td><td>§5.3, T1.7</td><td>I</td><td><code>PATCH /subtasks/{id}/status</code> → <code>FINISHED</code> cho subtask có vai trò</td><td>Bị từ chối. Subtask tự do vẫn đặt <code>FINISHED</code> được.</td><td>☐</td></tr><tr><td>A7</td><td>§16.9, T3.6</td><td>I</td><td>Triển khai chiến dịch có hạng mục POST ×1, KOL_BOOKING ×1, WORKSHOP_SUPPORT ×1</td><td>Sinh 3 task cha: POST, KOL_BOOKING, <strong>WORKSHOP</strong>; mỗi task có đủ subtask theo danh mục, assignee null, <code>dueDate</code> = hạn task cha, TODO.</td><td>☐</td></tr><tr><td>A8</td><td>T1.2</td><td>U</td><td><code>PackageOfferingValidator</code> với service type mới</td><td><code>SHORT_VIDEO → &quot;video&quot;</code>, <code>KOL_BOOKING → &quot;KOL&quot;</code>, <code>EMAIL_NEWSLETTER → &quot;bản tin&quot;</code>; đơn vị khác → lỗi.</td><td>☐</td></tr><tr><td>A9</td><td>Spec 13.1, T8.7</td><td>E</td><td>Manager tạo task POST tay → mở &quot;Gợi ý theo danh mục&quot;, bỏ <code>POST_RESEARCH</code>, gán 4 người, thêm 1 subtask tự do</td><td>Tạo 4 subtask có badge vai trò + 1 subtask tự do không badge; subtask có vai trò không có tuỳ chọn FINISHED thủ công.</td><td>☐</td></tr></tbody></table><h2 id="b-quyen-sua-phan-backend" tabindex="-1">B. Quyền sửa phần (backend) <a class="header-anchor" href="#b-quyen-sua-phan-backend" aria-label="Permalink to &quot;B. Quyền sửa phần (backend)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Map</th><th>Tầng</th><th>Bước / Input</th><th>Mong đợi</th><th>KQ</th></tr></thead><tbody><tr><td>B1</td><td>AC4, spec 13.2</td><td>I</td><td><code>content</code> lưu caption P1 qua <code>POST /tasks/P1/post</code></td><td>200; revision <code>POST.CAPTION</code> +1.</td><td>☐</td></tr><tr><td>B2</td><td>AC4, AC8, spec 13.2</td><td>I</td><td><code>content</code> gửi <code>SavePostRequest</code> đổi cả caption và media</td><td><code>FORBIDDEN</code>; không trường nào được lưu (không lưu một phần).</td><td>☐</td></tr><tr><td>B3</td><td>AC8</td><td>I</td><td><code>content</code> gửi request giữ nguyên media/kênh, chỉ đổi caption</td><td>200 (trường không đổi không bị tính là sửa).</td><td>☐</td></tr><tr><td>B4</td><td>AC4, §5.2</td><td>I</td><td><code>POST.CAPTION</code> ở <code>SUBMITTED</code>; <code>content</code> lưu caption</td><td><code>FORBIDDEN</code> (<code>tasks.sectionActions.locked</code>).</td><td>☐</td></tr><tr><td>B5</td><td>AC5, spec 13.4</td><td>I</td><td><code>free</code> sửa lần lượt BRIEF, CAPTION, MEDIA, CHANNELS</td><td>Đều <code>FORBIDDEN</code>.</td><td>☐</td></tr><tr><td>B6</td><td>AC6</td><td>I</td><td><code>coord</code> và <code>mgr</code> sửa mọi phần khi phần <code>DRAFT</code> và khi phần <code>INTERNAL_APPROVED</code></td><td>200; phần đang <code>INTERNAL_APPROVED</code> về <code>SUBMITTED</code>.</td><td>☐</td></tr><tr><td>B7</td><td>§5.2</td><td>I</td><td><code>mgr</code> sửa phần O đã <code>CLIENT_APPROVED</code></td><td>200; phần về <code>SUBMITTED</code>, phải qua lại nội bộ + Client.</td><td>☐</td></tr><tr><td>B8</td><td>AC7, spec 13.3</td><td>I</td><td><code>edit</code> sửa <code>POST.CAPTION</code> khi <code>DRAFT</code></td><td><code>FORBIDDEN</code>.</td><td>☐</td></tr><tr><td>B9</td><td>AC7, spec 13.3, §3.1</td><td>I</td><td><code>content</code> nộp <code>POST.CAPTION</code>; <code>edit</code> sửa</td><td>200. Sau đó <code>content</code> sửa → <code>FORBIDDEN</code> cho tới khi phần <code>RETURNED</code>.</td><td>☐</td></tr><tr><td>B10</td><td>§4 hợp quyền</td><td>U</td><td>Một người giữ subtask <code>POST_CONTENT</code> + <code>POST_MEDIA</code></td><td>Sửa được cả CAPTION và MEDIA.</td><td>☐</td></tr><tr><td>B11</td><td>§4, spec 11</td><td>I</td><td><code>content</code> và <code>content2</code> cùng vai trò <code>POST_CONTENT</code></td><td>Cả hai sửa được CAPTION.</td><td>☐</td></tr><tr><td>B12</td><td>§4 phần không chủ</td><td>U</td><td>Task không có subtask <code>POST_RESEARCH</code>; <code>content</code> sửa BRIEF; <code>coord</code> sửa BRIEF</td><td><code>content</code> → <code>FORBIDDEN</code>; <code>coord</code> → 200.</td><td>☐</td></tr><tr><td>B13</td><td>§11 subtask huỷ</td><td>I</td><td>Huỷ (<code>CANCELLED</code>) subtask <code>POST_MEDIA</code> khi MEDIA đang <code>SUBMITTED</code>; <code>media</code> sửa; <code>coord</code> sửa</td><td>Nội dung giữ nguyên. <code>media</code> → <code>FORBIDDEN</code>; <code>coord</code> → 200.</td><td>☐</td></tr><tr><td>B14</td><td>§11 đổi assignee</td><td>I</td><td>Đổi assignee subtask <code>POST_MEDIA</code> từ <code>media</code> sang <code>content2</code></td><td>Nội dung + trạng thái MEDIA giữ nguyên; <code>content2</code> có quyền, <code>media</code> mất quyền.</td><td>☐</td></tr><tr><td>B15</td><td>T3.2</td><td>I</td><td><code>VIDEO_PUBLISH</code> lưu <code>targetPlatforms = [THREADS]</code> cho SHORT_VIDEO</td><td><code>VALIDATION_ERROR</code>; <code>[TIKTOK, INSTAGRAM, FACEBOOK]</code> → 200.</td><td>☐</td></tr><tr><td>B16</td><td>T3.3</td><td>I</td><td><code>SURVEY_DISTRIBUTE</code> gọi <code>POST /tasks/{id}/survey</code>; <code>SURVEY_DESIGN</code> gọi</td><td>Lần 1 <code>FORBIDDEN</code>; lần 2 200. WORKSHOP: chỉ chủ <code>WORKSHOP.REGISTRATION</code> lưu form được.</td><td>☐</td></tr><tr><td>B17</td><td>T2.6</td><td>I</td><td><code>PATCH /sections/EVENT.AGENDA</code> với content sai schema (vd <code>agenda</code> không phải list)</td><td><code>VALIDATION_ERROR</code>; không tạo document.</td><td>☐</td></tr><tr><td>B18</td><td>Spec 13.8, §5.4</td><td>I</td><td>Hai phiên cùng đọc revision 3 của CAPTION; cả hai <code>PATCH</code> với <code>expectedRevision = 3</code></td><td>Phiên đầu 200 (revision 4); phiên sau <code>TASK_REVISION_CONFLICT</code>.</td><td>☐</td></tr><tr><td>B19</td><td>§5.4</td><td>I</td><td>Hai phiên sửa hai phần khác nhau (CAPTION, MEDIA) cùng lúc, qua <code>PATCH /sections</code> hoặc <code>POST /tasks/{id}/post</code> có <code>sectionRevisions</code></td><td>Cả hai 200, không chặn nhau; lưu bài chỉ ghi trường của phần đã khai báo.</td><td>☐</td></tr><tr><td>B20</td><td>T2.6 lazy create</td><td>I</td><td>Hai request đầu tiên đồng thời tạo document cho cùng <code>{taskId, sectionKey}</code></td><td>Một 200, một <code>TASK_REVISION_CONFLICT</code>; collection chỉ có 1 document.</td><td>☐</td></tr></tbody></table><h2 id="c-xem-phan-loc-theo-nguoi-xem" tabindex="-1">C. Xem phần &amp; lọc theo người xem <a class="header-anchor" href="#c-xem-phan-loc-theo-nguoi-xem" aria-label="Permalink to &quot;C. Xem phần &amp; lọc theo người xem&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Map</th><th>Tầng</th><th>Bước / Input</th><th>Mong đợi</th><th>KQ</th></tr></thead><tbody><tr><td>C1</td><td>T2.5</td><td>I</td><td><code>GET /tasks/P1/sections</code> khi chưa có document phần nào</td><td>Trả đủ 4 phần ảo <code>DRAFT</code>, <code>revision = 0</code>; không ghi gì vào DB.</td><td>☐</td></tr><tr><td>C2</td><td>§16.10</td><td>I</td><td><code>outsider</code> gọi <code>GET /sections</code></td><td>Không có phần I (BRIEF); vẫn thấy phần O.</td><td>☐</td></tr><tr><td>C3</td><td>§16.10</td><td>I</td><td><code>res</code>, <code>sup</code>, <code>free</code>, <code>owner</code> gọi <code>GET /sections</code></td><td>Đều thấy phần I.</td><td>☐</td></tr><tr><td>C4</td><td>AC10, spec 13.5</td><td>I</td><td><code>client</code> gọi <code>GET /sections</code> khi CAPTION <code>SUBMITTED</code>, MEDIA <code>INTERNAL_APPROVED</code>, BRIEF <code>INTERNAL_APPROVED</code></td><td>Chỉ trả MEDIA. Không có BRIEF, không có CAPTION. Không lộ trường của phần I trong JSON (kiểm cả nested).</td><td>☐</td></tr><tr><td>C5</td><td>AC10</td><td>I</td><td><code>client</code> gọi <code>GET /sections</code> cho task KOL, PRESS, EVENT_PLAN</td><td>KOL: không có <code>KOL.DEAL</code> (giá). PRESS: không có <code>MEDIA_LIST</code>, <code>CONTACT_LOG</code>. EVENT: không có <code>LOGISTICS</code>, <code>RUNSHEET</code>.</td><td>☐</td></tr><tr><td>C6</td><td>T2.5</td><td>I</td><td>Response cho <code>content</code></td><td>Có <code>canEdit/canSubmit/canApprove/canReturn</code>, <code>ownerSubtaskIds</code>, <code>ownerNames</code> đúng.</td><td>☐</td></tr><tr><td>C7</td><td>§11, <code>requiresClientApproval=false</code></td><td>I</td><td>Task không cần Client duyệt; <code>client</code> gọi <code>GET /sections</code></td><td>Không có phần nào ở trạng thái chờ Client; phần O dừng ở <code>INTERNAL_APPROVED</code>.</td><td>☐</td></tr></tbody></table><h2 id="d-vong-đoi-phan-duyet" tabindex="-1">D. Vòng đời phần &amp; duyệt <a class="header-anchor" href="#d-vong-đoi-phan-duyet" aria-label="Permalink to &quot;D. Vòng đời phần &amp; duyệt&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Map</th><th>Tầng</th><th>Bước / Input</th><th>Mong đợi</th><th>KQ</th></tr></thead><tbody><tr><td>D1</td><td>§5.1, T2.9</td><td>I</td><td>Đủ vòng CAPTION: <code>content</code> submit → <code>mgr</code> approve → <code>client</code> approve</td><td><code>DRAFT → SUBMITTED → INTERNAL_APPROVED → CLIENT_APPROVED</code>; mỗi bước ghi 1 event.</td><td>☐</td></tr><tr><td>D2</td><td>AC9</td><td>I</td><td><code>content</code>, <code>coord</code>, <code>free</code> gọi approve CAPTION <code>SUBMITTED</code></td><td>Đều <code>FORBIDDEN</code>.</td><td>☐</td></tr><tr><td>D3</td><td>AC9</td><td>I</td><td><code>sup</code> approve MEDIA; <code>sup</code> approve CAPTION</td><td>MEDIA → 200; CAPTION (không thuộc subtask của sup) → <code>FORBIDDEN</code>.</td><td>☐</td></tr><tr><td>D4</td><td>§5.1</td><td>I</td><td><code>client</code> approve phần đang <code>SUBMITTED</code></td><td><code>FORBIDDEN</code> hoặc <code>SECTION_INVALID_TRANSITION</code> (Client chỉ duyệt sau Manager).</td><td>☐</td></tr><tr><td>D5</td><td>§5.1</td><td>I</td><td><code>client</code> approve/return phần I (<code>BRIEF</code> <code>INTERNAL_APPROVED</code>)</td><td><code>FORBIDDEN</code>.</td><td>☐</td></tr><tr><td>D6</td><td>§5.1</td><td>I</td><td><code>content</code> submit phần đang <code>SUBMITTED</code>; <code>mgr</code> approve phần <code>DRAFT</code></td><td><code>SECTION_INVALID_TRANSITION</code>.</td><td>☐</td></tr><tr><td>D7</td><td>§10</td><td>I</td><td><code>mgr</code> return không có <code>note</code> / note rỗng</td><td><code>VALIDATION_ERROR</code> (<code>tasks.sectionActions.noteRequired</code>).</td><td>☐</td></tr><tr><td>D8</td><td>AC11, spec 13.6</td><td>I</td><td>CAPTION <code>CLIENT_APPROVED</code>, MEDIA <code>INTERNAL_APPROVED</code>; <code>client</code> return MEDIA với note</td><td>MEDIA → <code>RETURNED</code>, <code>returnNote</code> lưu; <code>media</code> sửa được lại; CAPTION vẫn <code>CLIENT_APPROVED</code>; <code>media</code> nhận thông báo.</td><td>☐</td></tr><tr><td>D9</td><td>§5.1 reopen</td><td>I</td><td><code>mgr</code> reopen CAPTION <code>INTERNAL_APPROVED</code> khi task cha chưa nộp</td><td>→ <code>RETURNED</code>. <code>coord</code> reopen → <code>FORBIDDEN</code>. Reopen sau khi task cha đã nộp → <code>SECTION_INVALID_TRANSITION</code>.</td><td>☐</td></tr><tr><td>D10</td><td>§5.1 phần I</td><td>U</td><td>BRIEF <code>INTERNAL_APPROVED</code></td><td>Được tính là trạng thái cuối.</td><td>☐</td></tr><tr><td>D11</td><td>§5.1, <code>requiresClientApproval=false</code></td><td>U</td><td>Phần O <code>INTERNAL_APPROVED</code></td><td>Trạng thái cuối; không set <code>clientPendingSince</code>.</td><td>☐</td></tr></tbody></table><h2 id="e-subtask-tu-đong-nop-task-cha" tabindex="-1">E. Subtask tự động &amp; nộp task cha <a class="header-anchor" href="#e-subtask-tu-đong-nop-task-cha" aria-label="Permalink to &quot;E. Subtask tự động &amp; nộp task cha&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Map</th><th>Tầng</th><th>Bước / Input</th><th>Mong đợi</th><th>KQ</th></tr></thead><tbody><tr><td>E1</td><td>§5.3, T3.5</td><td>I</td><td>Phần duy nhất của <code>POST_MEDIA</code> đạt cuối</td><td>Subtask <code>POST_MEDIA</code> tự <code>FINISHED</code>.</td><td>☐</td></tr><tr><td>E2</td><td>§5.3, T3.5</td><td>I</td><td>Client trả MEDIA (tiếp E1)</td><td>Subtask về <code>IN_PROGRESS</code>.</td><td>☐</td></tr><tr><td>E3</td><td>§5.3, T3.5</td><td>I</td><td><code>VIDEO_PUBLISH</code> sở hữu CAPTION + CHANNELS; chỉ CAPTION đạt cuối</td><td>Subtask chưa <code>FINISHED</code>; đủ cả hai mới <code>FINISHED</code>.</td><td>☐</td></tr><tr><td>E4</td><td>AC12, spec 13.7</td><td>I</td><td><code>coord</code> nộp P1 khi CAPTION còn <code>SUBMITTED</code></td><td><code>TASK_SECTIONS_UNAPPROVED</code>.</td><td>☐</td></tr><tr><td>E5</td><td>AC12, §5.3</td><td>I</td><td>Mọi phần <code>INTERNAL_APPROVED</code>+ nhưng còn subtask tự do chưa xong</td><td><code>TASK_SUBTASKS_UNFINISHED</code> (luật cũ vẫn chạy).</td><td>☐</td></tr><tr><td>E6</td><td>§16.5</td><td>I</td><td>Mọi phần O <code>CLIENT_APPROVED</code>, phần I <code>INTERNAL_APPROVED</code></td><td>Task cha tự sang trạng thái đã duyệt. Không có duyệt Client cấp task: lúc chờ, task ở <code>IN_REVIEW</code>/<code>reviewStep = CLIENT</code> nhưng Client duyệt/trả cấp task → <code>WRONG_APPROVAL_STEP</code>, chỉ duyệt từng phần.</td><td>☐</td></tr><tr><td>E7</td><td>§5.3</td><td>I</td><td><code>content</code> (chủ phần, không phải điều phối) nộp task cha</td><td><code>FORBIDDEN</code>.</td><td>☐</td></tr><tr><td>E8</td><td>§11 bỏ hết vai trò</td><td>I</td><td>Task POST chỉ có subtask tự do</td><td>Nộp task cha theo luồng cũ, không kiểm phần.</td><td>☐</td></tr></tbody></table><h2 id="f-phien-ban-nhat-ky" tabindex="-1">F. Phiên bản &amp; nhật ký <a class="header-anchor" href="#f-phien-ban-nhat-ky" aria-label="Permalink to &quot;F. Phiên bản &amp; nhật ký&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Map</th><th>Tầng</th><th>Bước / Input</th><th>Mong đợi</th><th>KQ</th></tr></thead><tbody><tr><td>F1</td><td>§16.12, T2.7</td><td>I</td><td>Submit CAPTION 3 lần (có trả lại giữa các lần)</td><td><code>task_section_versions</code> có <code>versionNo</code> 1, 2, 3 với snapshot caption thật (lấy từ <code>PostDocument</code>).</td><td>☐</td></tr><tr><td>F2</td><td>§16.12</td><td>I</td><td>Submit <code>SURVEY.FORM</code></td><td>Version chứa câu hỏi survey thật.</td><td>☐</td></tr><tr><td>F3</td><td>§16.12</td><td>I</td><td>Mọi hành động submit/approve/return/reopen</td><td>Ghi <code>task_section_events</code> gồm actor, action, note, thời điểm. Không có endpoint xoá version/event.</td><td>☐</td></tr><tr><td>F4</td><td>§16.13</td><td>I</td><td><code>content</code> restore v1 khi CAPTION <code>RETURNED</code></td><td>Caption nháp = v1; phần vẫn chưa nộp, phải nộp lại.</td><td>☐</td></tr><tr><td>F5</td><td>§16.13</td><td>I</td><td><code>content</code> restore khi CAPTION <code>SUBMITTED</code>; <code>free</code> restore</td><td>Đều <code>FORBIDDEN</code>. <code>coord</code>, <code>mgr</code> restore ở mọi trạng thái → 200, phần đã duyệt về <code>SUBMITTED</code>.</td><td>☐</td></tr><tr><td>F6</td><td>§16.14</td><td>I</td><td><code>client</code> gọi <code>GET /sections/{key}/versions</code> và <code>/versions/1</code></td><td><code>FORBIDDEN</code>.</td><td>☐</td></tr><tr><td>F7</td><td>T7.3</td><td>E</td><td>Mở <code>SectionVersionDrawer</code>, chọn 2 bản so sánh, khôi phục</td><td>Hiển thị khác biệt; khôi phục cập nhật nội dung và trạng thái phần.</td><td>☐</td></tr></tbody></table><h2 id="g-thong-bao-nhac-huy-lich" tabindex="-1">G. Thông báo, nhắc, huỷ lịch <a class="header-anchor" href="#g-thong-bao-nhac-huy-lich" aria-label="Permalink to &quot;G. Thông báo, nhắc, huỷ lịch&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Map</th><th>Tầng</th><th>Bước / Input</th><th>Mong đợi</th><th>KQ</th></tr></thead><tbody><tr><td>G1</td><td>§16.7, T4.1</td><td>I</td><td>Submit / approve / return / reopen</td><td>Mỗi sự kiện tạo in-app notification cho đúng người; <code>actionUrl</code> mở trình soạn.</td><td>☐</td></tr><tr><td>G2</td><td>§16.7, T4.2</td><td>I</td><td>Manager approve phần O (task cần Client duyệt)</td><td>Gửi email &quot;Có phần chờ Client duyệt&quot; tới Client, đúng ngôn ngữ vi/en.</td><td>☐</td></tr><tr><td>G3</td><td>§16.7, T4.2</td><td>I</td><td>Phần bị trả</td><td>Email &quot;Phần của bạn bị trả lại&quot; tới chủ phần, kèm note.</td><td>☐</td></tr><tr><td>G4</td><td>§16.7, T4.3</td><td>U</td><td>Job chạy với: phần A chờ 47h; B chờ 49h chưa nhắc; C chờ 100h, nhắc 20h trước; D chờ 100h, nhắc 50h trước</td><td>Chỉ nhắc B và D; cập nhật <code>clientReminderSentAt</code>. Không phần nào tự đổi trạng thái.</td><td>☐</td></tr><tr><td>G5</td><td>§11, T4.4, T4.5</td><td>I</td><td>P1 đã duyệt, post <code>SCHEDULED</code>, <code>scheduledAt</code> sau 1h; <code>client</code> return CAPTION</td><td>Task cha về <code>IN_PROGRESS</code>; post → <code>DRAFT</code>, <code>scheduledAt = null</code>; <code>pub</code> nhận thông báo. Chạy <code>PostSchedulePublishJob</code> với <code>now</code> sau giờ cũ → không đăng.</td><td>☐</td></tr><tr><td>G6</td><td>T4.4</td><td>I</td><td>Post đã <code>PUBLISHED</code>, Client trả phần</td><td>Post không đổi; thông báo <code>pub</code> kèm danh sách post không huỷ được.</td><td>☐</td></tr><tr><td>G7</td><td>T4.5</td><td>I</td><td>N1 đã lên lịch batch (<code>SCHEDULED</code>); <code>client</code> return <code>EMAIL.CONTENT</code></td><td><code>MailBatchService.cancelSystem(batchId)</code> được gọi; batch bị huỷ; chủ <code>EMAIL_SEND</code> nhận thông báo.</td><td>☐</td></tr><tr><td>G8</td><td>T4.5</td><td>I</td><td>Batch đã gửi xong, Client trả phần</td><td>Batch không đổi, không lỗi.</td><td>☐</td></tr></tbody></table><h2 id="h-newsletter" tabindex="-1">H. Newsletter <a class="header-anchor" href="#h-newsletter" aria-label="Permalink to &quot;H. Newsletter&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Map</th><th>Tầng</th><th>Bước / Input</th><th>Mong đợi</th><th>KQ</th></tr></thead><tbody><tr><td>H1</td><td>AC13, spec 13.9</td><td>I</td><td><code>mgr</code> import <code>contacts-10.csv</code> vào G1</td><td><code>{imported: 7, skippedNoConsent: 2, skippedSuppressed: 1, skippedInvalid: 0}</code>; entry có <code>consent</code>, <code>consentSource</code>, <code>importedAt</code>.</td><td>☐</td></tr><tr><td>H2</td><td>AC13</td><td>I</td><td>CSV có <code>consent</code> = <code>TRUE</code>, <code>Yes</code>, <code>1</code>, <code>y</code>, rỗng</td><td>3 giá trị đầu nhận; <code>y</code> và rỗng bị loại.</td><td>☐</td></tr><tr><td>H3</td><td>AC13, §11</td><td>I</td><td>CSV có cùng email 2 lần, 1 email sai định dạng</td><td>Giữ 1 dòng; dòng sai vào <code>skippedInvalid</code>.</td><td>☐</td></tr><tr><td>H4</td><td>§10</td><td>I</td><td>CSV thiếu cột <code>consent</code>; file không phải CSV</td><td><code>VALIDATION_ERROR</code> (<code>mailTemplate.contactImport.invalidFile</code>).</td><td>☐</td></tr><tr><td>H5</td><td>§9.2</td><td>I</td><td><code>content</code> (Creator) gọi import</td><td><code>FORBIDDEN</code>. <code>owner</code> → 200.</td><td>☐</td></tr><tr><td>H6</td><td>AC14, spec 13.10</td><td>I</td><td><code>EMAIL.CONTENT</code> <code>CLIENT_APPROVED</code>, <code>EMAIL.DESIGN</code> <code>INTERNAL_APPROVED</code>; chủ <code>EMAIL_SEND</code> gọi send</td><td><code>NEWSLETTER_NOT_APPROVED</code>.</td><td>☐</td></tr><tr><td>H7</td><td>AC14</td><td>I</td><td>Cả hai <code>CLIENT_APPROVED</code>; <code>content</code> (không phải chủ <code>EMAIL_SEND</code>) gọi send</td><td><code>FORBIDDEN</code>.</td><td>☐</td></tr><tr><td>H8</td><td>AC14, AC16, AC17, spec 13.10</td><td>I</td><td>Cả hai <code>CLIENT_APPROVED</code>; chủ <code>EMAIL_SEND</code> gửi tới G1</td><td>Tạo batch <code>kind = NEWSLETTER</code>; <code>batchId</code> lưu trong content <code>EMAIL.AUDIENCE</code>; mỗi mail có link <code>/public/mail/unsubscribe</code>; From domain BrandHub, tên hiển thị &quot;Brand X&quot;.</td><td>☐</td></tr><tr><td>H9</td><td>AC14</td><td>I</td><td>N1 với <code>requiresClientApproval = false</code>, CONTENT và DESIGN <code>INTERNAL_APPROVED</code></td><td>Gửi được.</td><td>☐</td></tr><tr><td>H10</td><td>T5.7</td><td>I</td><td><code>send-test</code></td><td>Chỉ gửi tới email người gọi; không tăng quota tháng.</td><td>☐</td></tr><tr><td>H11</td><td>AC15, spec 13.11</td><td>U+I</td><td>A1 gói BASIC đã dùng 1.000 trong tháng; gửi tiếp</td><td><code>MAIL_MONTHLY_QUOTA_EXCEEDED</code>, response có số còn lại = 0.</td><td>☐</td></tr><tr><td>H12</td><td>§16.2</td><td>I</td><td>W1 dùng 600, W2 (cùng A1) gửi 500</td><td>Chặn (còn 400); quota tính chung theo agency.</td><td>☐</td></tr><tr><td>H13</td><td>AC15</td><td>U</td><td>Sang tháng mới theo <code>Asia/Ho_Chi_Minh</code> (23:59 ngày cuối → 00:00 ngày 1)</td><td>Bộ đếm reset đúng mốc giờ VN.</td><td>☐</td></tr><tr><td>H14</td><td>AC15, §11</td><td>I</td><td>Còn 50 quota, batch 80 người</td><td>50 gửi, 30 <code>DEFERRED</code>; mail đã gửi giữ nguyên.</td><td>☐</td></tr><tr><td>H15</td><td>AC15, §16.1</td><td>I</td><td>Gửi newsletter 500 mail trong ngày</td><td><code>MailQuotaService</code> (100/ngày/workspace) không bị tiêu; mail hệ thống (OTP) vẫn gửi được. Vượt <code>newsletter.rate.per-day</code> → phần dư <code>DEFERRED</code>.</td><td>☐</td></tr><tr><td>H16</td><td>T5.5</td><td>I</td><td>Hàng đợi có batch newsletter và mail hệ thống</td><td><code>deliverNext</code> ưu tiên mail hệ thống.</td><td>☐</td></tr><tr><td>H17</td><td>AC16, §16.6</td><td>I</td><td>Người nhận unsubscribe từ newsletter W1; gửi newsletter W2 (cùng C1)</td><td>Người đó bị loại ở W2. Mail hệ thống tới người đó không bị suppression theo Client chặn.</td><td>☐</td></tr><tr><td>H18</td><td>T5.8</td><td>I</td><td><code>GET /mail-quota</code></td><td>Có <code>monthlyUsed</code>, <code>monthlyLimit = 1000</code>, <code>planName = BASIC</code>.</td><td>☐</td></tr><tr><td>H19</td><td>§16.3, T5.9</td><td>I</td><td><code>GET /sections</code> của N1 sau khi gửi</td><td><code>EMAIL.REPORT</code> có đã gửi / thành công / lỗi-bounce / huỷ đăng ký từ batch; không có open/click; chỉ ô nhận xét được lưu.</td><td>☐</td></tr></tbody></table><h2 id="i-xuat-file" tabindex="-1">I. Xuất file <a class="header-anchor" href="#i-xuat-file" aria-label="Permalink to &quot;I. Xuất file&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Map</th><th>Tầng</th><th>Bước / Input</th><th>Mong đợi</th><th>KQ</th></tr></thead><tbody><tr><td>I1</td><td>§16.11, T6.2</td><td>I</td><td><code>mgr</code> xuất task PRESS</td><td>File DOCX; có <code>PRESS.RELEASE</code>, <code>PRESS.COVERAGE</code>; <strong>không</strong> có nội dung <code>MEDIA_LIST</code>, <code>CONTACT_LOG</code>.</td><td>☐</td></tr><tr><td>I2</td><td>§16.11</td><td>I</td><td><code>mgr</code> xuất task KOL</td><td>PDF; không chứa giá trong <code>KOL.DEAL</code> (grep text PDF).</td><td>☐</td></tr><tr><td>I3</td><td>§16.11</td><td>I</td><td>Agency xuất khi có phần chưa <code>CLIENT_APPROVED</code></td><td>Phần đó có dấu &quot;Bản nháp&quot;; file có logo Client.</td><td>☐</td></tr><tr><td>I4</td><td>§16.11</td><td>I</td><td><code>client</code> xuất</td><td>Chỉ phần <code>CLIENT_APPROVED</code>; không có dấu &quot;Bản nháp&quot;.</td><td>☐</td></tr><tr><td>I5</td><td>§16.11</td><td>I</td><td><code>outsider</code> xuất</td><td>Không phải thành viên workspace → <code>WORKSPACE_ACCESS_DENIED</code> (như mọi API workspace). Creator trong workspace nhưng không tham gia task → <code>FORBIDDEN</code>.</td><td>☐</td></tr></tbody></table><h2 id="j-web-ui" tabindex="-1">J. Web UI <a class="header-anchor" href="#j-web-ui" aria-label="Permalink to &quot;J. Web UI&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Map</th><th>Tầng</th><th>Bước / Input</th><th>Mong đợi</th><th>KQ</th></tr></thead><tbody><tr><td>J1</td><td>Spec 13.1–8, T7.5</td><td>E</td><td>Luồng POST đầy đủ: Manager tạo subtask → Research/Content/Media/Publishing sửa đúng phần → Editing sửa caption sau khi Content nộp → Manager duyệt từng phần → Client duyệt 1 phần, trả 1 phần → chủ phần sửa, nộp lại → Client duyệt → task cha đã duyệt</td><td>Mỗi bước đúng trạng thái; nút hiện theo <code>can*</code>.</td><td>☐</td></tr><tr><td>J2</td><td>§8, T7.4</td><td>E</td><td><code>content</code> mở trình soạn P1</td><td>CAPTION sửa được; MEDIA, CHANNELS, BRIEF hiện nội dung nhưng input disabled + icon khoá + tooltip &quot;Phần của {tên}&quot;.</td><td>☐</td></tr><tr><td>J3</td><td>§12</td><td>E</td><td>Lần lượt tạo các trạng thái khối phần</td><td>Đủ: loading skeleton, empty (gợi ý theo vai trò), saving, saved, locked, returned (banner note), approved (badge), error (toast, giữ nội dung chưa lưu).</td><td>☐</td></tr><tr><td>J4</td><td>§12, T7.2</td><td>E</td><td>Mở trình soạn ở 2 tab, sửa cùng phần, lưu cả hai</td><td>Tab sau hiện banner xung đột + nút tải lại; nội dung đang gõ không mất trước khi tải lại.</td><td>☐</td></tr><tr><td>J5</td><td>T7.4, §11</td><td>E</td><td>Mở SHORT_VIDEO</td><td>Có khối <code>VIDEO.SCRIPT</code>; <code>VIDEO.SHOOT</code>, <code>VIDEO.EDIT</code> hiện placeholder; phần vẫn nộp/duyệt được.</td><td>☐</td></tr><tr><td>J6</td><td>T8.1</td><td>E</td><td>Mở trình soạn từng loại: SURVEY, EVENT_PLAN, PRESS, KOL, WORKSHOP, EMAIL</td><td>Route <code>/workspaces/:id/tasks/:taskId/editor</code> mở đúng editor; đủ khối phần theo spec §3.</td><td>☐</td></tr><tr><td>J7</td><td>T8.4 (chốt 2026-11-10)</td><td>E</td><td>Mở task EVENT_PLAN / PRESS cũ có <code>planContent</code> / <code>recommendations</code></td><td>Khối chỉ-đọc &quot;Nội dung cũ&quot; ở trên; không sửa được; dữ liệu cũ không bị đổi.</td><td>☐</td></tr><tr><td>J8</td><td>T8.2</td><td>E</td><td>Thêm/xoá/sắp xếp dòng trong bảng agenda, vendor, shortlist</td><td>Lưu đúng thứ tự; validate trường bắt buộc.</td><td>☐</td></tr><tr><td>J9</td><td>T8.6</td><td>E</td><td>NewsletterEditor: soạn khối, xem preview, chọn nhóm, gửi test, gửi</td><td>Nút gửi disabled khi chưa đủ duyệt (tooltip lý do); preview khớp nội dung.</td><td>☐</td></tr><tr><td>J10</td><td>T8.8</td><td>E</td><td>Task detail P1 khi 3/4 phần đã duyệt</td><td>Hiện &quot;3/4 phần đã duyệt&quot; + nút mở trình soạn (mọi loại, không chỉ POST/SURVEY).</td><td>☐</td></tr><tr><td>J11</td><td>§16.15, T8.9</td><td>E</td><td>Timeline chiến dịch: 1 subtask quá hạn, 1 phần chờ Client</td><td>Hiện trạng thái phần + cờ trễ hạn và cờ chờ Client.</td><td>☐</td></tr><tr><td>J12</td><td>T8.10</td><td>E</td><td>Client portal: có 2 phần chờ; trả không note; trả có note; duyệt</td><td>Trả không note bị chặn ở form; danh sách cập nhật sau thao tác; hết phần → empty state &quot;Chưa có phần nào chờ duyệt&quot;. Không thấy phần I.</td><td>☐</td></tr><tr><td>J13</td><td>T8.11</td><td>E</td><td>Mail templates: import CSV, xem quota</td><td>Dialog hiện 4 con số; khu quota hiện <code>monthlyUsed/monthlyLimit</code> + tên gói.</td><td>☐</td></tr><tr><td>J14</td><td>T8.12</td><td>E</td><td>Nút xuất ở trình soạn và portal</td><td>Tải file đúng định dạng (DOCX/PDF).</td><td>☐</td></tr><tr><td>J15</td><td>T7.1</td><td>E</td><td>Lọc task theo 4 loại mới ở <code>TaskFilterBar</code>, <code>MyTasksSection</code>; tạo offering 3 service type mới</td><td>Nhãn đúng, lọc đúng; đơn vị hiển thị video / KOL / bản tin.</td><td>☐</td></tr></tbody></table><h2 id="k-mobile" tabindex="-1">K. Mobile <a class="header-anchor" href="#k-mobile" aria-label="Permalink to &quot;K. Mobile&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Map</th><th>Tầng</th><th>Bước / Input</th><th>Mong đợi</th><th>KQ</th></tr></thead><tbody><tr><td>K1</td><td>AC18, spec 13.12, T9.3</td><td>M</td><td><code>mgr</code> mở task P1 → tab &quot;Phần&quot;</td><td>Thấy nội dung từng phần chỉ-đọc; nút Duyệt / Trả lại theo <code>canApprove/canReturn</code>; không có nút sửa.</td><td>☐</td></tr><tr><td>K2</td><td>AC18</td><td>M</td><td><code>mgr</code> trả phần không note</td><td>Bị chặn; có note → gọi API, phần về <code>RETURNED</code>.</td><td>☐</td></tr><tr><td>K3</td><td>AC18</td><td>M</td><td><code>client</code> mở task</td><td>Chỉ thấy phần O đủ điều kiện; có nút Duyệt/Trả.</td><td>☐</td></tr><tr><td>K4</td><td>AC18</td><td>M</td><td><code>content</code> (Creator) mở task</td><td>Thấy subtask được giao + phần chỉ-đọc; không có nút duyệt.</td><td>☐</td></tr><tr><td>K5</td><td>T9.1</td><td>M</td><td>Danh sách task có 4 loại mới; ngôn ngữ EN</td><td>Nhãn đúng (không hiện &quot;Chiến dịch&quot; hay mã thô); <code>EVENT_PLAN</code> EN = &quot;Event plan&quot;, <code>WORKSHOP</code> EN = &quot;Workshop&quot;. Bộ lọc có 4 loại mới.</td><td>☐</td></tr><tr><td>K6</td><td>T9.4</td><td>M</td><td><code>npm test</code> mobile</td><td>Pass, gồm <code>TaskDetailScreen.test.tsx</code>.</td><td>☐</td></tr></tbody></table><h2 id="l-i18n-light-dark" tabindex="-1">L. i18n &amp; Light/Dark <a class="header-anchor" href="#l-i18n-light-dark" aria-label="Permalink to &quot;L. i18n &amp; Light/Dark&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Map</th><th>Tầng</th><th>Bước / Input</th><th>Mong đợi</th><th>KQ</th></tr></thead><tbody><tr><td>L1</td><td>AC19, T10.1, T10.2</td><td>U</td><td>Script so khoá <code>vi</code> vs <code>en</code> cho <code>tasks</code>, <code>editor</code>, <code>campaign</code>, <code>mailTemplate</code>, <code>client</code> (web) và locale mobile</td><td>Không lệch khoá; đủ namespace AC19 (<code>tasks.subtaskRoles.*</code>, <code>tasks.sections.*</code>, <code>tasks.sectionStatus.*</code>, <code>tasks.sectionActions.*</code>, <code>tasks.types.*</code>, <code>campaign.timeline.catalog.*</code>, <code>editor.sections.*</code>, <code>mailTemplate.contactImport.*</code>, <code>mailTemplate.quota.monthly*</code>).</td><td>☐</td></tr><tr><td>L2</td><td>AC19, T10.3</td><td>T</td><td>Grep chuỗi tiếng Việt/Anh trong JSX/TSX mới</td><td>Không có chuỗi hardcode.</td><td>☐</td></tr><tr><td>L3</td><td>AC19, spec 13.13</td><td>E</td><td>Đổi vi ↔ en trên mọi trình soạn mới, portal, dialog import, timeline</td><td>Không lộ key thô, không tràn/vỡ layout (nhãn EN dài hơn).</td><td>☐</td></tr><tr><td>L4</td><td>AC20, spec 13.14, T10.4</td><td>E+T</td><td>Chụp light &amp; dark: badge 5 trạng thái, khối khoá, banner chỉ-đọc, banner trả lại, banner xung đột, editor mới, portal</td><td>Đủ tương phản (WCAG AA cho chữ); không màu lạc theme.</td><td>☐</td></tr><tr><td>L5</td><td>AC20</td><td>T</td><td>Grep hex/rgb trong file mới</td><td>Không có; chỉ token / <code>dark:</code>.</td><td>☐</td></tr></tbody></table><h2 id="m-regression-migration" tabindex="-1">M. Regression &amp; migration <a class="header-anchor" href="#m-regression-migration" aria-label="Permalink to &quot;M. Regression &amp; migration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Map</th><th>Tầng</th><th>Bước / Input</th><th>Mong đợi</th><th>KQ</th></tr></thead><tbody><tr><td>M1</td><td>Spec 13.15, §5.3</td><td>I+E</td><td>P2 (task cũ): <code>coord</code> mở trình soạn, sửa caption/media/kênh, nộp</td><td>Như trước: quyền theo <code>TaskApprovalPolicy.assignee</code>; luồng duyệt <code>reviewStep = CLIENT</code> giữ nguyên.</td><td>☐</td></tr><tr><td>M2</td><td>§11</td><td>I</td><td>Task cũ đang <code>IN_REVIEW</code> trước deploy</td><td>Duyệt/trả theo luồng cũ, không bị chặn bởi luật phần.</td><td>☐</td></tr><tr><td>M3</td><td>T1.2</td><td>I</td><td>Task SURVEY cũ sinh từ <code>WORKSHOP_SUPPORT</code> trước đây</td><td>Giữ loại SURVEY, mở và sửa bình thường.</td><td>☐</td></tr><tr><td>M4</td><td>T1.4</td><td>I</td><td>Chạy migration mongosh trên DB test có dữ liệu cũ</td><td>Insert task 4 loại mới thành công; <code>subtaskRole</code> null/string hợp lệ; 3 collection mới đủ index (unique <code>{taskId,sectionKey}</code>, unique <code>{taskId,sectionKey,versionNo}</code>); task cũ không đổi. Chạy lại lần 2 không lỗi.</td><td>☐</td></tr><tr><td>M5</td><td>T1.4</td><td>T</td><td>So <code>init-mongo.js</code> với DB sau migration</td><td>Validator và index khớp (parity).</td><td>☐</td></tr><tr><td>M6</td><td>T5.1</td><td>I</td><td>Chạy migration SQL trên Postgres test có dữ liệu cũ</td><td><code>mail_batches.kind = &#39;TEMPLATE&#39;</code> cho bản ghi cũ; cột/bảng mới có; chạy lại không lỗi.</td><td>☐</td></tr><tr><td>M7</td><td>T1.9, T6.3</td><td>I</td><td><code>mvn test</code> + <code>mvn package</code> business-service</td><td>Pass.</td><td>☐</td></tr><tr><td>M8</td><td>T8.13</td><td>I</td><td><code>npm run build</code> + <code>npm test</code> web</td><td>Pass, không lỗi TS.</td><td>☐</td></tr><tr><td>M9</td><td>Luồng cũ</td><td>E</td><td>Chạy lại E2E sẵn có của task / editor / survey / mail-templates / client portal</td><td>Không fail mới.</td><td>☐</td></tr><tr><td>M10</td><td>T4.4</td><td>I</td><td><code>PostSchedulePublishJob</code> với post của task không có subtask vai trò</td><td>Hành vi đăng lịch không đổi.</td><td>☐</td></tr></tbody></table><hr><h2 id="ket-qua-chay" tabindex="-1">Kết quả chạy <a class="header-anchor" href="#ket-qua-chay" aria-label="Permalink to &quot;Kết quả chạy&quot;">​</a></h2><p><em>Ghi ở T10.5: ngày, lệnh đã chạy, số test pass/fail, ảnh chụp light/dark, việc còn lại.</em></p>',34)])])}const p=d(n,[["render",h]]);export{u as __pageData,p as default};
